    button.addEventListener('click', function() {
        const productName = this.closest('.product-card').querySelector('h3').textContent;
        cart.addItem(productName);
        this.textContent = 'Added!';
        this.style.backgroundColor = '#4ade80';
        setTimeout(() => {
            this.textContent = 'Add to Cart';
            this.style.backgroundColor = '';
        }, 2000);
    });
});

// Newsletter Subscription
document.getElementById('newsletter-form').addEventListener('submit', function(e) {
    e.preventDefault();
    const email = this.querySelector('input[type="email"]').value;

    if (email) {
        cart.showNotification(`Thank you! Check ${email} for updates.`);
        this.reset();
    }
});

// CTA Buttons
document.querySelectorAll('.cta-button').forEach(button => {
    button.addEventListener('click', function(e) {
        if (e.target.closest('.product-card') === null) {
            cart.showNotification('Exploring featured products...');
        }
    });
});

// Smooth scroll for navigation links
document.querySelectorAll('a[href^="#"]').forEach(link => {
    link.addEventListener('click', function(e) {
        const href = this.getAttribute('href');
        if (href !== '#') {
            e.preventDefault();
            const target = document.querySelector(href);
            if (target) {
                target.scrollIntoView({ behavior: 'smooth' });
            }
        }
    });
});

// Cart button click handler
document.querySelector('.cart-btn').addEventListener('click', function() {
    const itemCount = cart.getItemCount();
    if (itemCount === 0) {
        cart.showNotification('Your cart is empty');
    } else {
        cart.showNotification(`You have ${itemCount} item${itemCount !== 1 ? 's' : ''} in your cart`);
    }
});

// Lazy load images
if ('IntersectionObserver' in window) {
    const imageObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const img = entry.target;
                img.style.opacity = '1';
                observer.unobserve(img);
            }
        });
    });

    document.querySelectorAll('img').forEach(img => {
        img.style.opacity = '0';
        img.style.transition = 'opacity 0.3s ease';
        imageObserver.observe(img);
    });
}

