    .hero-content h2 {
        font-size: 2rem;
    }

    .nav-links {
        gap: var(--spacing-md);
        font-size: 0.9rem;
    }

    .section-title {
        font-size: 1.8rem;
    }

    .products-grid,
    .deals-grid,
