+    addItem(product) {
+        this.items.push(product);
+        localStorage.setItem('cartItems', JSON.stringify(this.items));
+        this.updateCartUI();
+        this.showNotification(`${product} added to cart`);
+    }
+
+    getItemCount() {
+        return this.items.length;
+    }
+
+    updateCartUI() {
